tryItExercises.solutionCode:
const { DatabaseSync } = require("node:sqlite");

const db = new DatabaseSync("data/clubs.db");

const findByFocus = db.prepare(`
  SELECT id, name, focus
  FROM clubs
  WHERE focus = ?
  ORDER BY id
`);

const rows = findByFocus.all("engineering");
console.log(rows);

