// Prepare an INSERT for name/focus.
// Run it with values, then read the inserted row by its generated id.

tryItExercises.solutionCode:
const { DatabaseSync } = require("node:sqlite");

const db = new DatabaseSync("data/clubs.db");

const insertClub = db.prepare(`
  INSERT INTO clubs (name, focus)
  VALUES (?, ?)
`);

const result = insertClub.run("Design Circle", "design");

const findClubById = db.prepare(`
  SELECT id, name, focus
  FROM clubs
  WHERE id = ?
`);

const createdClub = findClubById.get(Number(result.lastInsertRowid));
console.log(createdClub);
